Translate the following GNU C++11 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <iostream>
#include <cstdio>
#include <cstring>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

typedef long long ll;
const int MAXN = 66;

int r, c, n;
char s[MAXN];
vector<vector<ll>> comb(MAXN, vector<ll>(MAXN, 0));
ll cnt_a[MAXN], cnt_b[MAXN];
vector<ll> part[MAXN], part_zero[MAXN];

void build_comb() {
    for (int i = 0; i <= n; ++i) {
        comb[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
    }
}

ll diff(int conf, int a, int b) {
    ll res = 0;
    int i = 0;
    while (i < c + 1) {
        if (conf & (1 << i)) {
            ++b;
            ll u = comb[b - 1][r - 1];
            ll v = comb[n - b][r] - comb[a][r];
            res -= u * v;
        } else {
            ++a;
            ll u = comb[a - 1][r - 1];
            ll v = comb[n - a][r] - comb[b][r];
            res += u * v;
        }
        ++i;
    }
    return res;
}

bool ok(int conf) {
    for (int i = 0; i < c + 1; ++i) {
        char ch = s[2 * r + c + i];
        int bit = (conf >> i) & 1;
        if (ch == 'A' && bit == 1) return false;
        if (ch == 'B' && bit == 0) return false;
    }
    return true;
}

void second_part() {
    int lim = 1 << (c + 1);
    for (int conf = 0; conf < lim; ++conf) {
        int b = __builtin_popcount(conf);
        int a = c + 1 - b;
        ll val = diff(conf, r + c - a, r + c - b);
        if (ok(conf))
            part[a].push_back(val);
        else
            part_zero[a].push_back(val);
    }
    for (int i = 0; i <= c + 1; ++i) {
        sort(part[i].begin(), part[i].end());
        sort(part_zero[i].begin(), part_zero[i].end());
    }
}

ll coef(int conf) {
    int i, j;
    for (i = 0; i < c + 1; ++i)
        if (((conf >> i) & 1) != (conf & 1))
            break;
    for (j = i; j < c + 1; ++j) {
        char ch = s[2 * r - 1 + j];
        int bit = (conf >> j) & 1;
        if (ch == 'A' && bit == 1) return 0;
        if (ch == 'B' && bit == 0) return 0;
    }
    int sa = r - 1 + ((conf & 1) == 0 ? i : 0);
    int sb = r - 1 + ((conf & 1) == 1 ? i : 0);
    if (sa < cnt_a[2 * r - 2 + i]) return 0;
    if (sb < cnt_b[2 * r - 2 + i]) return 0;
    return comb[sa + sb - cnt_a[2 * r - 2 + i] - cnt_b[2 * r - 2 + i]][sa - cnt_a[2 * r - 2 + i]];
}

void upd(pair<ll, ll>& ans, pair<ll, ll> act) {
    if (act.first < 0) act.first = -act.first;
    if (ans.first < act.first) return;
    if (ans.first > act.first) {
        ans = act;
        return;
    }
    ans.second += act.second;
}

ll cnt_eq(vector<ll>& v, ll x) {
    auto l = lower_bound(v.begin(), v.end(), x);
    auto r = upper_bound(v.begin(), v.end(), x);
    return r - l;
}

ll first_part() {
    int lim = 1 << (c + 1);
    pair<ll, ll> ans = make_pair(1LL << 60, 0);
    for (int conf = 0; conf < lim; ++conf) {
        int b = __builtin_popcount(conf);
        int a = c + 1 - b;
        ll act = diff(conf, r - 1, r - 1);
        ll cf = coef(conf);
        auto it = lower_bound(part[c + 1 - a].begin(), part[c + 1 - a].end(), -act);
        if (it != part[c + 1 - a].end()) {
            if (ans.first >= abs(*it + act)) {
                ll c2 = cnt_eq(part[c + 1 - a], *it);
                upd(ans, make_pair(*it + act, cf * c2));
            }
        }
        if (it != part[c + 1 - a].begin()) {
            --it;
            if (ans.first >= abs(*it + act)) {
                ll c2 = cnt_eq(part[c + 1 - a], *it);
                upd(ans, make_pair(*it + act, cf * c2));
            }
        }
        cf = 0;
        it = lower_bound(part_zero[c + 1 - a].begin(), part_zero[c + 1 - a].end(), -act);
        if (it != part_zero[c + 1 - a].end()) {
            if (ans.first >= abs(*it + act)) {
                ll c2 = cnt_eq(part_zero[c + 1 - a], *it);
                upd(ans, make_pair(*it + act, cf * c2));
            }
        }
        if (it != part_zero[c + 1 - a].begin()) {
            --it;
            if (ans.first >= abs(*it + act)) {
                ll c2 = cnt_eq(part_zero[c + 1 - a], *it);
                upd(ans, make_pair(*it + act, cf * c2));
            }
        }
    }
    return ans.second;
}

int main() {
    scanf("%d%d\n%s", &r, &c, s + 1);
    n = 2 * (r + c);
    build_comb();
    for (int i = 1; i <= n; ++i) {
        cnt_a[i] = cnt_a[i - 1] + (s[i] == 'A');
        cnt_b[i] = cnt_b[i - 1] + (s[i] == 'B');
    }
    second_part();
    ll sol = first_part();
    printf("%lld", sol);
    return 0;
}
